 set<vector<uint8_t>> S6;for(size_t i=pats.size()-cnt[6];i<pats.size();i++)S6.insert(pats[i]);for(auto const&z:S6){if(!S6.count(compw(z))||!S6.count(swapw(z))){cerr<<"S6 symmetry fail\n";return 4;}}
 vector<Node>nd;nd.reserve(410000);nd.emplace_back();for(auto const&p:pats){int q=0;for(auto a:p){if(nd[q].nx[a]<0){nd[q].nx[a]=nd.size();nd.emplace_back();nd.back().par=q;nd.back().pch=a;}q=nd[q].nx[a];}nd[q].out=true;}queue<int>qu;for(int a=0;a<26;a++){int q=nd[0].nx[a];if(q>=0){qu.push(q);}else nd[0].nx[a]=0;}while(!qu.empty()){int r=qu.front();qu.pop();nd[r].out|=nd[nd[r].fail].out;for(int a=0;a<26;a++){int s=nd[r].nx[a];if(s>=0){nd[s].fail=nd[nd[r].fail].nx[a];qu.push(s);}else nd[r].nx[a]=nd[nd[r].fail].nx[a];}}
 vector<int>safe,si(nd.size(),-1);for(int q=0;q<(int)nd.size();q++)if(!nd[q].out){si[q]=safe.size();safe.push_back(q);}int sink=safe.size(),N=sink+1;vector<array<int,26>>T(N);for(int i=0;i<sink;i++){int q=safe[i];for(int a=0;a<26;a++){int r=nd[q].nx[a];T[i][a]=nd[r].out?sink:si[r];}}T[sink].fill(sink);vector<int>cls(N);cls[sink]=1;int oldk=2;while(1){unordered_map<array<int,27>,int,AH>M;M.reserve(N*2);vector<int>nc(N);int k=0;for(int q=0;q<N;q++){array<int,27>s;s[0]=(q==sink);for(int a=0;a<26;a++)s[a+1]=cls[T[q][a]];auto[it,ins]=M.emplace(s,k);if(ins)k++;nc[q]=it->second;}cls.swap(nc);cerr<<"classes="<<k<<"\n";if(k==oldk)break;oldk=k;}int K=*max_element(cls.begin(),cls.end())+1,sinkc=cls[sink];vector<int>cmap(K,-1),rep(K,-1);int dk=0;for(int c=0;c<K;c++)if(c!=sinkc)cmap[c]=dk++;for(int q=0;q<sink;q++)if(rep[cls[q]]<0)rep[cls[q]]=q;vector<array<int16_t,26>>TR(dk);for(int c=0;c<K;c++)if(c!=sinkc){int i=cmap[c],q=rep[c];for(int a=0;a<26;a++){int cc=cls[T[q][a]];TR[i][a]=(cc==sinkc)?-1:cmap[cc];}}int START=cmap[cls[si[0]]];auto wordOf=[&](int safidx){int node=safe[safidx];vector<uint8_t>w;while(node){w.push_back(nd[node].pch);node=nd[node].par;}reverse(w.begin(),w.end());return w;};auto walk=[&](const vector<uint8_t>&w){int q=0;for(auto a:w)q=nd[q].nx[a];return q;};vector<uint16_t>CM(dk),SM(dk);for(int c=0;c<K;c++)if(c!=sinkc){int i=cmap[c];auto ww=wordOf(rep[c]);int qc=walk(compw(ww)),qs=walk(swapw(ww));if(nd[qc].out||nd[qs].out){cerr<<"auto reject\n";return 5;}CM[i]=cmap[cls[si[qc]]];SM[i]=cmap[cls[si[qs]]];}
