 cout<<"R17 C041 cap3 minimal-six extension exact language checker\n"<<"base_patterns_le5="<<(pats.size()-cnt[6])<<"\ncap3_minimal_deficient_six="<<cnt[6]<<"\npatterns_total="<<pats.size()<<"\naho_nodes="<<nd.size()<<"\nsafe_aho_nodes="<<safe.size()<<"\nminimized_nonrejecting_states="<<dk<<"\nstart="<<START<<"\nEXACT_CAP3_MIN6_COUNT_PASS\nEXACT_SYMMETRY_CLOSURE_PASS\nEXACT_DFA_MINIMIZATION_PASS\nALL_EXACT_CHECKS_PASS\n";
 ofstream f("c041_dfa24555.h");f<<"#pragma once\nstatic constexpr int DFAK="<<dk<<",DFAAL=26,DFASTART="<<START<<";\nstatic const int16_t DFATR[DFAK][DFAAL]={\n";for(auto&r:TR){f<<"{";for(int a=0;a<26;a++){if(a)f<<',';f<<r[a];}f<<"},\n";}f<<"};\nstatic const uint16_t DFACM[DFAK]={";for(int i=0;i<dk;i++){if(i)f<<',';f<<CM[i];}f<<"};\n";
